  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["SW6", "R34", "R35"],
      "pins": ["SW6.1", "SW6.2", "SW6.3", "SW6.4", "R34.1", "R34.2", "R35.1", "R35.2"],
      "nets": ["/CAN0_P", "/CAN0_N", "/CAN1_P", "/CAN1_N", "Net-(R34-Pad2)", "Net-(R35-Pad2)"],
      "observed": "SW6's two independent poles are wired to cross-connect the CAN buses when switched on: one pole connects /CAN0_P to /CAN1_P; the other connects /CAN0_N to /CAN1_N through R34 and R35 in series.",
      "expected": "CAN0 and CAN1 should remain separate buses, as specified. If SW6 is intended to provide termination, each bus should instead be terminated across its own CAN_P and CAN_N pair.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "/CAN0_P : ... SW6.4(passive) ... /CAN1_P : ... SW6.3(passive)"
        },
        {
          "source": "netlist",
          "quote": "Net-(R34-Pad2) : R34.2(2,passive) SW6.1(passive) ; Net-(R35-Pad2) : R35.2(2,passive) SW6.2(passive)"
        },
        {
          "source": "netlist",
          "quote": "/CAN0_N : ... R34.1(1,passive) ... /CAN1_N : ... R35.1(1,passive)"
        },
        {
          "source": "spec",
          "quote": "two isolated CAN buses (CAN0, CAN1), each driven by its own MCP2515 SPI CAN controller"
        }
      ],
      "impact": "Turning on the switch couples the two CAN buses rather than independently terminating them. Traffic or faults on one bus can affect the other, and the resulting cross-bus resistor path is not a proper per-bus termination.",
      "confidence": 0.97
    },
    {
      "category": "bridged_nets",
      "components": ["U10", "U11"],
      "pins": ["U10.4", "U10.5", "U11.4", "U11.5"],
      "nets": ["GND"],
      "observed": "Both ground pins on each CAN transceiver—GND1 and GND2—are connected to the same GND net.",
      "expected": "For the specified isolated CAN interfaces, each transceiver's logic-side and bus-side grounds must remain galvanically isolated; GND2 should not be tied to GND1.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "GND ... U10.4(GND1,power_in) U10.5(GND2,power_in) U11.4(GND1,power_in) U11.5(GND2,power_in)"
        },
        {
          "source": "spec",
          "quote": "two isolated CAN buses (CAN0, CAN1), each driven by its own MCP2515 SPI CAN controller ... through an isolated CAN transceiver"
        }
      ],
      "impact": "The shared ground defeats the transceivers' galvanic isolation, allowing ground-potential differences and noise on the CAN side to couple into the logic ground.",
      "confidence": 0.99
    }
  ],
  "summary": "The netlist supports two functional deviations: SW6 can couple the nominally separate CAN buses, and both CAN transceivers have their logic and bus grounds tied together, defeating the specified galvanic isolation."
}

